From 3c6c9b2da75538b13ba1d3f16278944ad6452a7d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 04:20:10 +0100
Subject: [PATCH] components/calendar: Finish short touchpad swipes on the next
 page

Touchpads move the calendar with wheel events that drag it but never
flick it, so a quick swipe snapped back unless it passed half a page.
Flick to the next page when such a swipe ends past a sixth of a page.

BUG: 528586
---
 components/calendar/qml/InfiniteList.qml | 25 ++++++++++++++++++++++++
 1 file changed, 25 insertions(+)

diff --git a/components/calendar/qml/InfiniteList.qml b/components/calendar/qml/InfiniteList.qml
index d45e6df7c0..38388360fb 100644
--- a/components/calendar/qml/InfiniteList.qml
+++ b/components/calendar/qml/InfiniteList.qml
@@ -125,6 +125,31 @@ ListView {
         }
     }

+    // Touchpads drag the view with wheel events, which never end in a flick,
+    // so finish a short swipe by flicking to the page it was moving towards
+    property bool wheelDragging: false
+
+    WheelHandler {
+        acceptedDevices: PointerDevice.Mouse | PointerDevice.TouchPad
+        blocking: false
+        onWheel: wheel => {
+            if (wheel.phase === Qt.ScrollUpdate) {
+                root.wheelDragging = true;
+            }
+        }
+    }
+
+    onDragEnded: {
+        if (!wheelDragging) {
+            return;
+        }
+        wheelDragging = false;
+        const offset = contentY - (itemAtIndex(1)?.y ?? height);
+        if (Math.abs(offset) > height / 6) {
+            Qt.callLater(flick, 0, offset > 0 ? -maximumFlickVelocity : maximumFlickVelocity);
+        }
+    }
+
     /* ------------------------------- UI ENDS ----------------- MODEL MANIPULATING FUNCTIONS ----------------------------------- */


